package cl.dynasty.nexusbeacon.platform.classic;
import java.util.HashSet;import java.util.Set;import org.bukkit.Bukkit;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.inventory.Recipe;import org.bukkit.inventory.ShapedRecipe;import org.bukkit.plugin.Plugin;
public final class ClassicRecipeManager { private final NamespacedKey key;private final ClassicBeaconItemFactory items;private boolean registered;
 public ClassicRecipeManager(Plugin p,ClassicBeaconItemFactory i){key=new NamespacedKey(p,"nexus_beacon");items=i;}
 public boolean register(ConfigurationSection s){if(s==null||!s.getBoolean("enabled",true))return false;if(registered)return true;java.util.List<String> shape=s.getStringList("shape");if(shape.isEmpty())throw new IllegalArgumentException("Recipe shape missing");ShapedRecipe recipe=new ShapedRecipe(key,items.createNew(1));recipe.shape(shape.toArray(new String[shape.size()]));ConfigurationSection ingredients=s.getConfigurationSection("ingredients");if(ingredients==null)throw new IllegalArgumentException("Recipe ingredients missing");Set<Character> symbols=new HashSet<Character>();for(String row:shape)for(char c:row.toCharArray())if(c!=' ')symbols.add(Character.valueOf(c));for(Character c:symbols){String name=ingredients.getString(String.valueOf(c));Material m=name==null?null:Material.matchMaterial(name);if(m==null)throw new IllegalArgumentException("Unsupported recipe material: "+name);recipe.setIngredient(c.charValue(),m);}registered=Bukkit.addRecipe(recipe);return registered;}
 public void unregister(){if(registered){java.util.Iterator<Recipe> it=Bukkit.recipeIterator();while(it.hasNext()){Recipe recipe=it.next();if(recipe instanceof ShapedRecipe&&key.equals(((ShapedRecipe)recipe).getKey())){try{it.remove();}catch(UnsupportedOperationException ignored){}break;}}registered=false;}} public boolean isRegistered(){return registered;} public NamespacedKey getKey(){return key;}}
